def keypad_words(digits):
    if not digits:
        return []
    keypad = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    results = []
    def backtrack(i, path):
        if i == len(digits):
            results.append("".join(path))
            return
        for letter in keypad[digits[i]]:
            path.append(letter)
            backtrack(i + 1, path)
            path.pop()
    backtrack(0, [])
    results.sort()
    return results
